   const D=distanceAPI(),opts=D.config(cfg.household?.distanceModel||{}),data=project.distanceData,rows=data?.rows||[],n=(project.d||[]).length;
   const fields=[['centre','centreKm','Avstånd till valt centrum'],['transit','transitKm','Avstånd till kollektivtrafikpunkt'],['service','serviceKm','Avstånd till service eller dagligvaror'],['income','income','Median ekonomisk standard'],['bph','bph','Registrerade bilar per hushåll']];
   const table=fields.map(([key,field,label])=>'<tr><td>'+esc(label)+'</td><td>'+esc(rows.filter(r=>typeof r[field]==='number'&&Number.isFinite(r[field])).length)+' / '+esc(n)+'</td><td>'+esc(fmt(opts.coefficients[key]))+'</td></tr>').join('');
   const active=cfg.household?.kmMode==='deso_estimate',estimate=active?distanceEstimate(cfg,project):null;
   return '<article class="card"><h2>Valbar skattning av körsträcka per DeSO</h2><p><strong>Aktivt läge:</strong> '+(active?'Modellerad DeSO-fördelning':'Befintligt kommun- eller riksläge')+'. Kommunläget är grundinställning. DeSO-läget använder valda koefficienter som inte har skattats ur körsträckedata per DeSO eller ur resvaneundersökningar.</p><p>För varje indikator beräknas ett transformerat värde: log(1 + avstånd i km), log(ekonomisk standard) respektive log(1 + bilar per hushåll). Giltiga värden centreras mot kommunens bilvägda medel. Den relativa poängen är r(i) = exp(Σ β(k) × [x(i,k) − medel(k)]). Saknad indikator ger bidrag noll. Fördelningen blir K(i) = K(kommun) × f(i), där f(i) = max(minfaktor, min(maxfaktor, λ × r(i))). λ väljs så att Σ P(i) × f(i) = Σ P(i). Kommunens bastrafikarbete bevaras därmed även när gränserna används.</p><p>Faktorgränserna är '+esc(fmt(opts.minFactor))+'–'+esc(fmt(opts.maxFactor))+'. Vald lokal CV är '+esc(fmt(opts.residualCV))+'. Faktorgränserna gäller den centrala grundskattningen. Monte Carlo-variation kan ge värden utanför gränserna. Lokal variation normaliseras med P(i) × K(i); kommunankarets osäkerhet behandlas separat. Koefficienternas kunskapsosäkerhet täcks genom dokumenterade alternativa inställningar, inte genom ett påstått empiriskt konfidensintervall. Scenarier använder den beräknade basfördelningen; en förändrad närhetsindikator är inte i sig en belagd kausal åtgärdseffekt.</p><div class="table-wrap"><table class="calc-table"><thead><tr><th>Indikator</th><th>Datatäckning</th><th>Vald koefficient</th></tr></thead><tbody>'+table+'</tbody></table></div><p>Datatäckning betyder att ett numeriskt indikatorvärde finns, inte att årssträcka har observerats. Geografisk proxy, koordinaternas datum och saknade data framgår av underlagets metadata. Fågelvägsavstånd är inte gångtid; hållplatsnärhet är inte turtäthet. Saknade inkomster eller målpunkter fylls inte med påhittade värden.</p>'+(estimate?.warnings?.length?'<ul>'+estimate.warnings.map(w=>'<li>'+esc(w)+'</li>').join('')+'</ul>':'')+'<p>Variabelvalet stöds av Elldér (2015) och Berry och Börjesson (2026). Ingen numerisk koefficient har hämtats ur dessa studier. Inkomstens samband med hushållens totala körning får inte okritiskt överföras till körsträcka per bil när registrerat bilantal redan ingår. RVU Skåne 2023 kan vara ett framtida skattningsunderlag, men kräver separat föraresträcka, rätt vikter och dokumenterad överföring från höstdag till helår. '+sourceLinks(['ELLDER_2015','BERRY_BORJESSON_2026','RVU_SKANE_2023','SCB_INCOME_DESO','OSM_OVERPASS','TRAFIKLAB_GTFS'])+'</p></article>';
  }
  function render(cfg,project){
   const model=project.model==='household'?'B':'A',ps=parameters(cfg,project);
   const rows=ps.map(p=>'<tr><td>'+esc(p.name)+'<br><small>'+esc(p.id)+'</small></td><td>'+esc(fmt(p.activeValue))+' '+esc(p.unit||'')+'</td><td>'+esc(labels[p.effectiveStatus]||p.effectiveStatus)+'</td><td>'+esc(p.rationale)+'<br>'+sourceLinks(p.sources)+'</td></tr>').join('');
   const sourceCards=sources.map(s=>'<div class="source"><strong>'+esc(s.title)+'</strong><p>'+esc(s.use)+'</p><p class="small">'+esc(s.verification)+' '+esc(s.locator||'')+'</p>'+(safeUrl(s.url)?'<a href="'+safeUrl(s.url)+'" target="_blank" rel="noopener noreferrer">Öppna originalkälla ↗</a>':'<p class="small">Öppet modellval i paketets parameterregister.</p>')+'</div>').join('');
   return '<article class="card"><h2>Vägvis 2.3.0 · beräkningsbeskrivning</h2><p>Vägvis använder två öppet definierade aktivitetsmodeller och en gemensam livscykelberäkning. Modell A beräknar fordonens körning på vägar inom ett område. Modell B tillskriver hushållens personbilar deras samlade körning, oavsett körplats. Modellerna svarar på olika frågor och ska inte summeras.</p><p><strong>Aktiv modell '+esc(model)+':</strong> '+esc(registry.boundaries?.[model]||'')+'</p>'+dataStatus(project,cfg)+'</article>'+
    '<article class="card"><h2>Aktivitet och formler</h2><p><strong>A:</strong> trafikarbete per fordonsklass = Σ(länklängd inom området × ÅDT för den geometrin × antal dagar i året × klassandel). Beräkningsåret '+esc(cfg.year)+' använder '+esc((new Date(Date.UTC(cfg.year+1,0,1))-new Date(Date.UTC(cfg.year,0,1)))/86400000)+' dagar. MVD får endast räknas om med dokumenterad faktor, år och riktning. ÅDT-formeln stöds av Trafikverket (2015). '+sourceLinks(['TV_AADT_METHOD'])+'</p><p><strong>B:</strong> trafikarbete = bilstock i aktiv rad × radens aktiva årliga körsträcka per bil. Bilar per hushåll är en beskrivning av indata: bilstock / hushåll. Det är radens bilstock som används i beräkningen. Kommunläget använder inlästa kommunvärden, riksläget använder gemensamt riksvärde och det valbara DeSO-läget använder en kommunankrad modellskattning. Registrerade bilar, årsslutsstock och körsträckestatistik kan avse olika målpopulationer. I det medföljande underlaget är bilstock (TAB6589), hushåll (TAB6568) och folkmängd (TAB6574) registeruppgifter per DeSO för 31 december 2024. Om registeruttag för hushåll eller befolkning saknas används en geografisk proxyfördelning, som då redovisas med egen status. Bilar per hushåll redovisas inte när hushållsunderlaget saknar positiv nämnare; registrerade bilar och deras trafikarbete behålls ändå. Körsträckestatistiken lokaliserar inte körningen (Trafikanalys, u.å.). '+sourceLinks(['SCB_CARS','SCB_HOUSEHOLDS','TRAFANALYS'])+'</p><p><strong>Gemensam livscykel:</strong> utsläpp [ton CO2e] = Σ(fordonskm × klassens faktor [g CO2e/fordonskm]) / 1 000 000. Faktorn summerar fossil direktutsläppspost, bränsleförsörjning, elproduktion, fordonsproduktion, batteriproduktion, underhåll och slutbehandling. Produktionen fördelas på livslängd i kilometer. Fordonsmix viktar varje drivlina.</p><p><strong>Energi:</strong> direktutsläpp = MJ/km × termisk andel × fossil energiandel × fossil förbränningsfaktor + övriga direkta växthusgaser. Bränsleförsörjning = MJ/km × termisk andel × (fossil andel × fossil försörjningsfaktor + biogen andel × biogen försörjningsfaktor). Elproduktion = eldriftsandel × kWh/km / laddverkningsgrad × elens klimatfaktor. Batteri = kapacitet × produktionsfaktor / livslängd.</p><p><strong>Redovisning:</strong> TTW avser avgasposten. Drift inklusive elproduktion = TTW + elproduktion. Posten <code>wtt</code> omfattar både bränsleförsörjning och elproduktion; dessa delar kan särredovisas och ska inte adderas en gång till. Biogen avgas-CO2 och potentiell återvinningskredit visas separat. Krediten dras inte av från huvudresultatet.</p></article>'+
    distanceSection(cfg,project)+
    '<article class="card"><h2>Omfattning och källstöd</h2><p>Detta är en livscykelscreening. Vägbyggnad, vägunderhåll, laddinfrastruktur och parkeringsbyggnader ingår inte. Utsläpp från tillverkning och energiförsörjning behöver inte ske i det redovisade geografiska området. Slutbehandling och separat återvinningspotential innebär inte att en fullständig sluten cradle-to-cradle-cykel är verifierad.</p><p>Sedan version 2.2.0 förankrar Vägvis de viktigaste talen i officiell statistik och en samlad livscykelkälla: energianvändningen per fordonsklass är kalibrerad så att direktutsläppen motsvarar Trafikverkets nationella siffror för 2024; personbilens tillverkning, batteri, underhåll och livslängd följer ICCT (2025); elens klimatfaktor är Naturvårdsverkets värde för nordisk elmix; fordonsandelar per vägtyp följer Trafikverkets normalvärden; fossila bränslens livscykelintensitet följer direktiv (EU) 2015/652. I grundfallet kalibreras modell A per kommun mot officiell eller kommunal statistik för direktutsläpp 2024. Värden markerade <em>Valt modellantagande</em> saknar direkt extern källa och är tillgängliga för granskning och byte. '+sourceLinks(['TV_UTSLAPP_2025','ICCT_LCA_2025','NV_KLIMATKLIVET_2025','TV_NORMALVARDEN','FQD_2015_652'])+'</p><p>Monte Carlo-intervall är villkorade av valda variationskoefficienter och samvariation. De ska inte tolkas som empiriskt heltäckande konfidensintervall. Områden summeras inom varje dragning; marginalintervall mellan områden ska inte adderas.</p></article>'+
    '<article class="card"><h2>Aktuella parametrar och antaganden</h2><p>Värden med konfigurationssökväg läses från aktiva inställningar. Trafikschabloner är fasta reservvärden och används bara när motsvarande vägdata saknas. B använder samma generiska personbilsprofil som klass Personbil i A, inklusive dess aktiva fordonsmix. B:s körsträcka och tre variationskoefficienter visas som separata parametrar. Projektets exporterade källkvitto innehåller även underlagets metadata och aktuella hushållsinställningar.</p><div class="table-wrap"><table class="calc-table calc-wrap"><thead><tr><th>Parameter</th><th>Aktuellt värde</th><th>Status</th><th>Förklaring och referens</th></tr></thead><tbody>'+rows+'</tbody></table></div></article>'+
    (model==='B'?'<article class="card"><h2>Scenarier</h2><p>En åtgärdsrubrik har ingen belagd automatisk procenteffekt. Ange egen effekt, täckning, målgrupp och motivering i scenariot. Grundeffekterna är noll. Scenarioantaganden är framåtblickande modellval; ett samband i en resvaneundersökning visar inte i sig en kausal åtgärdseffekt.</p></article>':'')+
    '<article class="card"><h2>Referenser och datakontroll</h2><p>'+esc(availability(project))+' Källbeskrivningar nedan anger vad varje källa faktiskt stödjer. Källor kontrollerade 23–26 oktober 2026 om annat datum inte anges. Faktiska datauttag och täckning framgår av respektive datakvitto.</p>'+sourceCards+'</article>'+
    '<article class="card"><h2>Använd och komplettera indata</h2><ol><li>Alla medföljande grunddata är redan inlästa och modellen kan användas direkt. Exakt källstatus, år och datatäckning visas ovan.</li><li>I modell B kan en validerad indikatorfil läsas in med knappen Läs in indikatorfil · JSON i den valbara DeSO-delmodellen. Filen måste följa Vägvis indikatorformat och samma beräkningsår och DeSO-version. Saknade indikatorvärden behålls som saknade.</li><li>I modell A kan en förberedd och validerad väg-GeoJSON läsas in under Indata &amp; kvalitet. Filen ersätter vägarna för vald kommun och behöver dokumenterade trafikflöden, år, riktning och fordonsfördelning. MVD kräver dokumenterad omräkning till ÅDT; en vanlig kartfil visar inte trafikmängden.</li><li>Projektets indata och inställningar kan sparas och öppnas som projekt-JSON. Direktimport av valfria Excel- eller CSV-filer stöds inte.</li><li>För en fullständig publicerad datauppdatering ersätts vagvis_data.json i GitHub med en ny levererad och kontrollerad fil. Den stora datafilen behöver inte redigeras manuellt. Import i webbläsaren ändrar det öppna projektet; spara projektet för att bevara ändringarna.</li><li>Viktade resvaneundersökningar kan användas för framtida skattning och validering först när urval, bilförare, fordonskilometer och helårsomräkning dokumenteras.</li></ol></article>';
  }
  return {parameters,receipt,summary,render};
 }
 return {create,labels};
});

