/* Vägvis 2.3.0 interface. Every displayed result is produced by the current
   independent engines and current project; no historical result is a fallback. */
(function () {
  'use strict';
  const V = window.Vagvis, H = window.VagvisHouseholds, S = window.VagvisScenarios;
  const E = window.VagvisEvidence, M = window.VagvisMaps, D = window.VagvisDistance;
  const $ = id => document.getElementById(id);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const clone = value => JSON.parse(JSON.stringify(value));
