    return '<article class="card distance-model-panel" id="distance-model-panel"><h2>Valbar körsträckeskattning per DeSO</h2>'+notice('<strong>Modellerad DeSO-fördelning – valda antaganden, inte validerad mot körsträckor per DeSO.</strong> Kommunens bilvägda referens behålls. Delmodellen fördelar körsträcka mellan områden och flyttar inga registerbilar.')+'<p>Indikatorerna ger relativa skillnader. Avstånd är fågelvägsproxies från bostadsgator, inte uppmätt restid. Saknade indikatorer får neutralt bidrag och visas nedan. Service avser dagligvaror; kollektivnoder anger fysisk närhet och inte trafikens frekvens. Kontrollera datakällornas år mot beräkningsåret.</p>'+(error?'<p class="notice error">'+esc(error)+'</p>':'')+table(['Indikator','Tillgängliga värden i '+esc(cityName()),'Mått'],distanceFeatures.map(([key,field,label,unit])=>'<tr><td>'+esc(label)+'</td><td>'+number(available(field))+' av '+number(stock.length)+' DeSO'+(available(field)<stock.length?'<small>Saknat underlag ger neutralt bidrag.</small>':'')+(coeff[key]===0?'<small>Indikatorn är avstängd (koefficient 0).</small>':available(field)===0?'<small>Indikatorn bidrar inte: underlag saknas.</small>':'')+'</td><td>'+esc(unit)+'</td></tr>').join(''))+'<h3>Valda koefficienter</h3><p>Förvalen är öppet valda, redigerbara modellantaganden. De är inte koefficienter skattade från resvaneundersökningar. Positiv koefficient ökar den relativa körsträckan när indikatorn ökar. Noll stänger av indikatorn. Samband på områdesnivå är inte bevisade åtgärdseffekter.</p><div class="controls">'+distanceFeatures.map(([key,field,label])=>fieldControl(label,'household.distanceModel.coefficients.'+key,coeff[key]??0,{min:-2,max:2,step:.01,unit:'vald koefficient; 0 = avstängd'})).join('')+fieldControl('Lägsta faktor mot kommunreferens','household.distanceModel.minFactor',dm.minFactor??.65,{min:.05,max:1,step:.05,unit:'vald begränsning'})+fieldControl('Högsta faktor mot kommunreferens','household.distanceModel.maxFactor',dm.maxFactor??1.5,{min:1,max:5,step:.05,unit:'vald begränsning'})+fieldControl('Lokal kvarvarande körsträckevariation · CV','household.distanceModel.residualCV',dm.residualCV??.35,{min:0,max:3,step:.05,unit:'antagen variation; faktorgränserna gäller grundskattningen'})+'</div>'+(ce?'<p><strong>Avstämning för '+esc(cityName())+':</strong> kommunreferens '+number(ce.anchorKm)+' km/bil och år. Skattat trafikarbete '+number(ce.estimatedVkm)+' fordonskm; referens '+number(ce.targetVkm)+' fordonskm.</p>':'')+'<div class="button-row">'+button('Återställ delmodellens antaganden','id="reset-distance-model"')+button('Läs in indikatorfil · JSON','id="import-distance-data"')+button('Beräkningsbeskrivning och källor','data-view="method"')+'</div><p class="small">Alla medföljande grunddata är redan inlästa. Komplettera delmodellen med knappen Läs in indikatorfil · JSON och en validerad indikatorfil för samma år och DeSO-version. En fullständig publicerad datauppdatering görs genom att ersätta vagvis_data.json i GitHub med en ny levererad fil. Ändringar kräver ny beräkning. Nya hushåll i ett exploateringsscenario ärver områdets skattade körsträcka om inget eget km-värde anges. Åtgärdernas förändring av trafikarbetet beräknas därefter och normaliseras inte bort.</p></article>';
  }
  // Named separately because distanceFeatures also has a field-name column.
  const fieldControl=(label,path,value,options)=>field(label,path,value,options);
  function distanceExplanation(rs) {
    const est=active().distancePrepared?.distanceEstimate;if(!est)return '';
    const selectedCodes=new Set(rs.map(r=>r.kod)),details=(est.rows||[]).filter(r=>selectedCodes.has(r.kod));
    return '<details class="calc-details" id="distance-explanation"><summary>Visa områdesfaktorer och använda indikatorer</summary><p>Modellens positiva relativa poäng begränsas och justeras gemensamt inom kommunen så att det bilvägda medlet är exakt kommunreferensen. Saknade indikatorer har neutralt bidrag. Fördelningen är ett antagande tills den prövats mot oberoende körsträckedata.</p>'+table(['DeSO','Kommunreferens km/bil','Områdesfaktor','Skattad km/bil','Källstatus'],details.map(r=>'<tr><td>'+esc(r.kod)+'</td><td class="numeric">'+number(r.anchorKm)+'</td><td class="numeric">'+number(r.factor,4)+'</td><td class="numeric">'+number(r.kmPerCar)+'</td><td>Modellerad skattning</td></tr>').join(''))+(details.length===1?table(['Indikator','Råvärde','Vald koefficient','Bidrag till log-poäng'],distanceFeatures.map(([key,field,label])=>{const x=details[0].components?.[key]||{};return '<tr><td>'+esc(label)+'</td><td class="numeric">'+number(x.value,3)+(x.value==null?'<small>Saknas; neutralt bidrag.</small>':'')+'</td><td class="numeric">'+number(x.coefficient,3)+'</td><td class="numeric">'+number(x.contribution,4)+(x.used?'':'<small>Inget aktivt bidrag.</small>')+'</td></tr>';}).join(''))+'<p>Bidragen är logaritmiska modellpoäng, inte procent. Indikatorernas råvärden och koefficienter sparas i beräkningskvittot.</p>':'')+'</details>';
  }
  function distanceMethodView() {
    const source=active().project.distanceData,dm=active().cfg.household.distanceModel||D?.DEFAULTS||{};
    const ss=Array.isArray(source?.metadata?.sources)?source.metadata.sources:[];
    const sources=ss.map(s=>typeof s==='string'?'<li>'+esc(s)+'</li>':'<li>'+esc(s.title||s.name||s.id||'Datakälla')+(s.url?' · <a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">Öppna källa ↗</a>':'')+(s.dataYear?' · uppgiftsår '+esc(s.dataYear):'')+(s.status?' · '+esc(({not_downloaded:'ej hämtat; inget indikatorbidrag',spatial_proxy:'rumslig proxy',bundled_register:'inläst registerunderlag',model_choice:'valt modellantagande'})[s.status]||s.status):'')+'</li>').join('');
    return '<article class="card distance-model-method"><h2>Körsträcka per DeSO · valbar delmodell</h2>'+notice('Källstatus: <strong>modellerad skattning</strong>. Förklarande variabler är källbelagda där data finns. Koefficienter, begränsningar och CV är valda antaganden; ingen empirisk DeSO-validering påstås.')+'<p>För varje indikator används ett bidrag till en relativ positiv körsträckepoäng. Avstånd omvandlas med log(1 + km), bilar per hushåll med log(1 + bilar/hushåll) och ekonomisk standard med log(inkomst). Bidragen centreras kring kommunens bilvägda medel av respektive omvandlad indikator. Poängen begränsas mellan valda faktorer och normaliseras med registrerade bilantal så att kommunens referens bevaras. Varken bilinnehav eller kommunens trafikarbete ökar automatiskt av denna områdesfördelning.</p><p class="calc-formula">Kᵢ = Kkommun × områdesfaktorᵢ; Σ(Pᵢ × Kᵢ) = Σ(Pᵢ) × Kkommun</p><p>Standardkoefficienter är centrum 0,12, kollektivnod 0,08, dagligvaror 0,08, ekonomisk standard 0,10 och bilar per hushåll 0. De är valda startantaganden, inte resultat ur de citerade studierna. Positivt avståndsbidrag betyder att större avstånd kan ge längre skattad körsträcka. Bilar per hushåll är avstängt från början eftersom riktningen för körsträcka per bil inte är entydigt belagd och bilantal redan ingår i trafikarbetet.</p><p>DeSO-indikatorernas uppgiftsår är '+esc(source?.dataYear??'inte angivet')+' och geografin DeSO '+esc(source?.desoVersion??'inte angiven')+'. Kollektivnärhet avser fysisk större nod, inte turtäthet. Serviceproxyn avser dagligvaruhandel. Startpunkter på bostadsgator approximerar var bilarna hör hemma; de är inte faktiska bostadsadresser eller en observerad befolkningsfördelning. Nyare kartdata är en överföring till basåret och har separat källdatum.</p><p>SCB levererar enligt besked körsträckor ned till kommunnivå. RUS-kommunvärdena avser samtliga personbilar som varit i trafik någon gång under året, medan B:s registerbilar avser folkbokförda personers bilar vid årets slut. Kommunankaret är därför en dokumenterad överföring. RVU bör användas för framtida skattning och validering med bilförares fordonskilometer, nollresdagar, analysvikter och dokumenterad omräkning till helår. Personkilometer och fordonskilometer får inte blandas.</p><h3>Osäkerhet och scenario</h3><p>Lokal residualvariation normaliseras med områdenas fordonskilometer i varje simulering så att den inte ändrar kommunens trafikarbete. Kommunens gemensamma osäkerhet och livscykelfaktorer varierar separat. Faktorgränserna gäller den centrala grundskattningen. Monte Carlo-variation kan ge körsträckor utanför dessa gränser. Koefficienterna hålls fasta inom en körning; deras osäkerhet undersöks genom att användaren jämför olika koefficientval. Modellintervallet täcker därför inte all osäkerhet om sambanden. Den skattade basfördelningen hålls fast när åtgärder tillämpas, så åtgärdernas förändring normaliseras inte bort.</p>'+(sources?'<h3>Indikatorkällor och hämtningsunderlag</h3><ul>'+sources+'</ul>':'')+((source?.metadata?.caveats||[]).length?'<h3>Databegränsningar</h3><ul>'+source.metadata.caveats.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ul>':'')+'<h3>Forskningsstöd för variabelval</h3><p>Berry och Börjesson (2026) skiljer mellan bilinnehav och körning i svenska hushåll; en total inkomstelasticitet får inte direkt bli en faktor för km per bil när bilantalet redan ingår. Elldér (2015) visar samband mellan bebyggelse, närhet och reslängd, med olika förklaringsvärde för olika resärenden. Dessa källor stödjer att pröva variablerna, men belägger inte delmodellens numeriska förval.</p><ol><li>Berry, C. och Börjesson, M. (2026). Are the rich reaching saturation: Income and fuel price elasticities of car ownership and use. <em>Economics of Transportation</em>, 45, 100448. <a href="https://doi.org/10.1016/j.ecotra.2026.100448" target="_blank" rel="noopener noreferrer">doi:10.1016/j.ecotra.2026.100448</a>.</li><li>Elldér, E. (2015). <em>The changing role and importance of the built environment for daily travel in Sweden.</em> Göteborgs universitet. <a href="https://gupea.ub.gu.se/server/api/core/bitstreams/0bec7cb4-5023-4785-9ac1-f3555f0c72f9/content" target="_blank" rel="noopener noreferrer">Fulltext</a>.</li></ol></article>';
  }
  function parametersView() {
    const c=active().cfg;
    let html='<article class="card"><h2>År och scenario</h2><p>Ändringar börjar gälla efter en ny beräkning. Ett ändrat beräkningsår hämtar inte nya trafikdata eller registeruppgifter.</p><div class="controls">'+field('Beräkningsår','year',c.year,{step:1,min:1900,max:2200})+field('Simuleringar','iterations',c.iterations,{step:100,min:100,max:30000})+field('Slumptalsfrö','seed',c.seed,{step:1,min:0})+field('Ändrat trafikarbete','trafficChange',c.trafficChange,{scale:100,min:-99,max:500,unit:'procent, endast scenario'})+field('Ökad elbilsandel','electrify',c.electrify,{scale:100,min:0,max:100,unit:'procentenheter, endast scenario'})+(isB()?field(householdRows().some(r=>H.kmLevel(r,{household:{...c.household,kmMode:'local'}})!=='riket')?'Körsträcka där lokala värden saknas':'Årlig körsträcka per bil','household.kmPerCar',c.household.kmPerCar,{min:0,max:100000,unit:'km / bil · år, riksmedelvärde 12 753'})+'<label class="field">Körsträcka per område<select class="input" data-path="household.kmMode">'+option('local','Kommunvärde eller eget DeSO-underlag',c.household.kmMode||'local')+option('national','Samma riksmedelvärde för alla',c.household.kmMode)+option('deso_estimate','Skattad körsträcka per DeSO · antaganden',c.household.kmMode)+'</select></label>':'')+'</div></article>';
    if(isB()&&c.household.kmMode==='deso_estimate')html+=distanceModelView();
    if(!isB()){const refs=(active().project.cities||[]).filter(x=>x.reference);html+='<article class="card"><h2>Beräkningsläge för modell A</h2><p>I <strong>kalibrerat läge</strong> (grundfall) skalas antagen trafik per kommun så att direktutsläppen motsvarar referensen för '+esc(c.year)+'. Uppmätta länkar skalas inte. I <strong>okalibrerat läge</strong> används vägklassernas schablonflöden direkt; det läget är till för validering och känslighetsanalys.</p><div class="controls"><label class="field">Läge<select class="input" data-path="mode"><option value="calibrated"'+(c.mode==='calibrated'?' selected':'')+'>Kalibrerat mot kommunreferens</option><option value="network"'+(c.mode==='network'?' selected':'')+'>Okalibrerad nätschablon</option></select></label></div>'+(refs.length?table(['Kommun','Referens TTW t CO₂e','År','CV','Källa'],refs.map(x=>'<tr><td>'+esc(x.name)+'</td><td class="numeric">'+number(x.reference.groups?.all??Object.values(x.reference.groups||{}).reduce((a,b)=>a+b,0))+'</td><td>'+esc(x.reference.year)+'</td><td class="numeric">'+number((x.reference.cv??c.uncertainty.reference)*100)+' %</td><td>'+esc(x.reference.source||'')+'</td></tr>').join(''),'ref-wrap'):'<p>Inga kommunreferenser finns i projektet.</p>')+'</article>';}
    html+='<article class="card"><h2>Gemensam livscykelmodell</h2><p>Numeriska värden är redigerbara modellval om det inte finns ett uttryckligt verifierat datauttag. Källor och exakt evidensstatus finns under Metod &amp; källor.</p><div class="controls">'+field('Elens klimatfaktor','electricity',c.electricity,{min:0,max:2000,unit:'g CO₂e/kWh'})+field('Batteriproduktion','batteryEF',c.batteryEF,{min:0,max:1000,unit:'kg CO₂e/kWh batteri'})+field('Laddverkningsgrad','chargeEfficiency',c.chargeEfficiency,{scale:100,min:10,max:100,unit:'procent'})+field('Laddhybridens elandel','phevElectric',c.phevElectric,{scale:100,min:0,max:100,unit:'procent av körningen'})+field('Energimultiplikator','energyScale',c.energyScale,{min:.01,max:10})+field('Produktionsmultiplikator','productionScale',c.productionScale,{min:.01,max:10})+field('Livslängdsmultiplikator','lifeScale',c.lifeScale,{min:.01,max:10})+'</div></article>';
    html+='<article class="card"><h2>Fordonsprofiler</h2>'+table(['Klass','Livstids-km','Kaross kg CO₂e','Batteri kWh','Bränsle MJ/km','El kWh/km','Underhåll g/km','Slut kg CO₂e'],c.profiles.filter(p=>!isB()||p.id==='car').map(p=>{const i=c.profiles.findIndex(x=>x.id===p.id);return '<tr><td>'+esc(p.name)+'</td>'+['life','body','battery','mj','kwh','maint','eol'].map(k=>'<td>'+field('',`profiles.${i}.${k}`,p[k],{min:k==='life'?1:0})+'</td>').join('')+'</tr>';}).join(''))+'<h3>Drivlineandelar · summera till 100 % per klass</h3>'+table(['Klass','Bensin %','Diesel %','Elhybrid %','El %','Laddhybrid %','Biogas %','HVO %'],c.profiles.filter(p=>!isB()||p.id==='car').map(p=>{const i=c.profiles.findIndex(x=>x.id===p.id);return '<tr><td>'+esc(p.name)+'</td>'+['petrol','diesel','hev','bev','phev','biogas','hvo'].map(k=>'<td>'+field('',`profiles.${i}.mix.${k}`,p.mix[k]||0,{min:0,max:100,scale:100})+'</td>').join('')+'</tr>';}).join(''))+'</article>';
    html+=exploitationView();
    html+='<article class="card"><h2>Antagen osäkerhet</h2>'+(isB()&&c.household.kmMode==='deso_estimate'?'<p>För den valbara DeSO-skattningen används delmodellens lokala CV i kortet ovan. Fälten för lokal variation utan områdesdata och uppmätt DeSO-körsträcka nedan används i de andra körsträckelägena.</p>':'')+'<p>Variationskoefficienterna är öppna modellantaganden. De är inte empiriskt skattade standardfel för varje DeSO. Korrelation och kommunvis summering hanteras i simuleringsmotorn.</p><div class="controls">'+Object.entries(c.uncertainty).map(([k,v])=>field(k,'uncertainty.'+k,v,{min:0,max:k==='mixConcentration'?100000:3})).join('')+(isB()?Object.entries(c.household.uncertainty||{}).map(([k,v])=>field(({distance:'Körsträcka, riksmedelvärde · CV',carStock:'Antal registrerade bilar · CV',allocation:'Lokal körsträckevariation utan områdesdata · CV',distanceLocal:'Körsträcka, kommun- eller DeSO-data · CV',allocationLocal:'Körsträcka uppmätt per DeSO · CV'})[k]||k,'household.uncertainty.'+k,v,{min:0,max:3,unit:k==='carStock'?'0 = registertal hålls fasta':k==='allocation'?'Modellerad lokal variation i km per bil; bilantalet flyttas inte':'Antagen variation i kommunens gemensamma km per bil'})).join(''):'')+'</div></article>';return html;
  }
  function exploitationView() {
    if(!isB())return '';
    const a=active().cfg.exploitation||{};
    return '<article class="card"><h2>Exploateringsscenario · nya hushåll</h2><p>Nya hushåll läggs till i det valda DeSO-området i scenariot. Bilar per nytt hushåll är ett eget antagande. Körsträckan för de nya bilarna är som standard samma som för områdets befintliga bilar och kan ändras. Åtgärderna tillämpas på både befintliga och nya hushåll. Ingen automatisk andel flyttas över till territoriell modell A.</p><label class="check"><input type="checkbox" id="exploitation-enabled"'+(a.enabled?' checked':'')+'> Aktivera nya hushåll</label><div class="controls"><label class="field">DeSO i '+esc(cityName())+'<select id="exploitation-deso">'+option('','Välj DeSO',a.deso)+active().project.areas.filter(x=>x.city===city&&x.level==='deso').map(x=>option(x.id,x.name,a.deso)).join('')+'</select></label>'+field('Nya hushåll','exploitation.newHouseholds',a.newHouseholds||0,{min:0,step:1})+field('Bilar per nytt hushåll','exploitation.carsPerHousehold',a.carsPerHousehold??1,{min:0,max:5})+field('km per ny bil och år','exploitation.kmPerCar',a.kmPerCar??(()=>{try{const t=a.deso?resolvedHouseholdRows().find(x=>x.kk===city&&x.kod===a.deso):null;return t?H.kmOf(t,active().cfg):active().cfg.household.kmPerCar;}catch(_){return null;}})(),{min:0,max:150000,unit:a.kmPerCar==null?'standard: områdets körsträcka':'eget värde'})+'</div><p class="small">Vald kommun för scenariot: '+esc(a.city||city)+'. Om du byter kommun, välj målområdet på nytt. Nytt trafikarbete före åtgärder = nya hushåll × bilar per hushåll × km per bil.</p></article>';
  }
  function measuresView() {
    if(!isB())return notice('Åtgärderna avser hushållens personbilar. Välj modell B för att ange deltagande och scenarioeffekter. För territoriella förändringar finns trafikförändring under Parametrar.');
    const st=active().cfg.areaScenario||{}, fx=S.effects(st);
    return '<article class="card"><h2>Fjorton valbara åtgärder</h2><p>Åtgärderna gäller samtliga kommuner i projektet. Varje effekt är en relativ förändring vid full nivå för den berörda målgruppen. Negativa tal betyder minskning. Alla förval är neutrala: noll anger att någon kvantifierad effekt ännu inte valts. Noll är inte ett belägg för att en verklig åtgärd saknar effekt.</p>'+notice('Trafikarbete avser hela förändringen i fordonskilometer. Bilinnehav multipliceras inte med trafikarbetet en gång till. Kvarvarande andelar multipliceras mellan åtgärder; överlapp kan fortfarande ge för stor sammanlagd effekt.')+'<p><strong>Aktuella faktorer:</strong> bilar '+number(fx.fCars,4)+' · fordonskm '+number(fx.fVkm,4)+' · energi per km '+number(fx.fEnergy,4)+'.</p>'+table(['Aktiv','Åtgärd','Omfattning %','Intensitet %','Bilar %','Fordonskm %','Energi/km %'],S.actions.map(a=>{const x=st[a.id]||{}, ef=S.effects({[a.id]:x}).contributions[0]?.effects||a.defaultEffects;return '<tr><td><input type="checkbox" data-action="'+a.id+'" data-action-key="enabled"'+(x.enabled?' checked':'')+' aria-label="Aktivera '+esc(a.name)+'"></td><td>'+esc(a.name)+'<small>'+esc(a.description)+'</small></td>'+[['coverage',x.coverage??1],['intensity',x.intensity??1],['cars',ef.cars],['vkm',ef.vkm],['energy',ef.energy]].map(([k,v])=>'<td><input class="input scenario-number" type="number" data-action="'+a.id+'" data-action-key="'+k+'" value="'+numberInput(v*100)+'" min="'+(['coverage','intensity'].includes(k)?0:-100)+'" max="'+(['coverage','intensity'].includes(k)?100:500)+'" step="1" aria-label="'+esc(a.name+' '+k)+'"></td>').join('')+'</tr>';}).join(''))+'<h3>Dokumenterat litteraturexempel</h3><p>PBL:s nederländska studie beskriver valda bilpooldeltagare. Förvalet väljer −30 % bilar och −17,5 % bilkilometer som överförda scenarioantaganden. Det är inte en kausal effekt skattad för svenska DeSO.</p>'+button('Välj PBL-exempel för bilpool','data-preset="carsharing_pbl2015"')+' '+button('Nollställ alla åtgärder','id="reset-actions"','ghost')+'<p><a href="https://www.pbl.nl/en/publications/impact-of-car-sharing-on-mobility-and-co2-emissions" target="_blank" rel="noopener noreferrer">Nijland, van Meerkerk och Hoen (2015), PBL ↗</a></p><label class="field">Egen motivering och underlag<textarea id="scenario-note" rows="3">'+esc(active().cfg.scenarioNote||'')+'</textarea></label>'+fx.warnings.map(w=>notice(esc(w))).join('')+'</article>';
  }
  const numberInput = value => Number.isFinite(value)?String(Math.round(value*1e8)/1e8):'';
  function controlView() {
    const result=active().result;
    const totals=['deso','district'].map(l=>{const subset=rows().filter(r=>r.city===city&&r.level===l&&r.central);return {level:l,n:subset.length,sum:subset.reduce((s,r)=>s+r.central.total,0)};});
