  function methodView() {
    const own='<article class="card"><h2>Fristående Vägvis 2.3.0</h2><p>Syftet är en spårbar screening av vägtrafikens årliga klimatpåverkan med två kompletterande systemgränser. Modell A räknar körning inom en yta. Modell B räknar hushållsanknutna personbilars körning oavsett var den sker. Resultaten besvarar olika frågor och ska inte summeras.</p><h3>Aktivitet och livscykel</h3><p>A: fordonskm = Σ (väglängd × ÅDT × dagar × fordonsandel). B: fordonskm = Σ (bilar i hushållsunderlaget × km per bil och år). Det medföljande paketet innehåller SCB:s registrerade personbilar per DeSO för 2024. Hushåll (TAB6568) och folkmängd (TAB6574) per DeSO är också SCB-registerdata för 2024. Registerkällan omfattar folkbokförda personers bilar, inklusive privatleasing och enskilda firmor; förmånsbilar ingår inte. Standardläget använder ett härlett kommunvärde från SCB:s körsträckedata (RUS), eller ett eget inläst DeSO-underlag om sådant finns, och annars riksmedelvärdet 12 753 km. SCB levererar körsträckor ned till kommunnivå. Kommunvärdet är en överföring till privatägda bilar i årsslutsbeståndet, inte en direkt uppmätt privatbilskörsträcka per DeSO. Som valbart alternativ finns en kommunankrad DeSO-skattning med öppet valda koefficienter för tillgänglighet, inkomst och bilinnehav. Den är inte validerad mot körsträckor per DeSO. Antagen lokal variation utan områdesdata är en modellbedömning och flyttar inte registrerade bilar mellan områden. Båda modellerna använder samma komponentvisa LCA-faktorer. I A kalibreras schablonflödena per kommun så att direktutsläppen motsvarar statistik för 2024; uppmätta länkar skalas inte. Direktutsläppen per km är olika i tätort och på landsbygd enligt Trafikverkets HBEFA-kvoter.</p><p>Årligt utsläpp = Σ (fordonskm × gram CO₂e per fordonskm) / 1 000 000. Sex komponenter ingår: direkta avgaser, energi i tidigare led, fordon, batteri, underhåll och slutbehandling. Biogen CO₂ och potentiell återvinningskredit visas separat. Fullständig cirkularitet eller en fullständigt verifierad cradle to cradle-analys påstås inte.</p><h3>Scenario och modellintervall</h3><p>För en åtgärd j är vikten omfattning × intensitet. Faktor för en storhet x är produkten av (1 + vikt × relativ effekt). Åtgärdens förändring av hela trafikarbetet innefattar dess bilinnehavseffekt. Energifaktorn tillämpas på driftens energikedja. Neutrala förval betyder att en kvantifierad effekt inte valts. Multiplikativ kombination är ett öppet modellval; verklig överlapp behöver undersökas.</p><p>Monte Carlo använder angivna osäkerhetsantaganden och gemensamma dragningar för basfall och scenario. Kommunen summeras inom varje dragning. Percentil 2,5–97,5 är ett villkorat modellintervall. I kalibrerat läge styrs kommuntotalens osäkerhet av referensens CV; i okalibrerat läge av kommunnivåfelet 0,45 som motsvarar den observerade avvikelsen mot kommunstatistik. Varken fullständig täckning av all osäkerhet eller kausala åtgärdseffekter garanteras.</p><h3>Arbetsgång</h3><ol><li>Välj systemgräns och kommun.</li><li>Granska källstatus, år, geografi och saknade data.</li><li>Dokumentera egna schabloner och scenarier under Parametrar och Åtgärder.</li><li>Beräkna, granska summering och undersök områden.</li><li>Exportera resultat, projekt och spårbarhetskvitto tillsammans.</li></ol></article>';
    return own+(isB()&&active().cfg.household.kmMode==='deso_estimate'?distanceMethodView():'')+(E?.render?E.render(active().cfg,active().project):'<article class="card"><p>Källregistret är inte laddat.</p></article>');
  }
  async function run() {
    if(busy)return; const current=model, token=++calculationToken, data=state[current];
    data.distancePrepared=null;data.distancePreparedKey=null;busy=true;cancelled=false;$('progress-box').hidden=false;$('progress-bar').style.width='0%';setMessage('Beräknar aktuella indata…');sync();
    const progress=(done,total)=>{if(token!==calculationToken)return;let f=typeof total==='number'&&total>0?done/total:typeof done==='number'?done:done?.fraction||0;if(f>1)f=f/100;f=Math.max(0,Math.min(1,f));$('progress-bar').style.width=(f*100)+'%';$('progress-label').textContent='Beräknar '+number(f*100)+' %';};
    try {
      V.validateConfig(data.cfg); if(current==='household')S.effects(data.cfg.areaScenario||{});
      const result=await (current==='household'?H.simulate(data.project,data.cfg,progress,()=>cancelled):V.simulate(data.project,data.cfg,progress,()=>cancelled));
      if(cancelled){setMessage('Beräkningen avbröts. Tidigare resultat är kvar.');return;}
      data.result=result;data.dirty=false;setMessage('Beräkningen är klar. Modellintervallen gäller de valda antagandena.');
    } catch(error) { setMessage(error.message||String(error),!cancelled); if(!cancelled)console.error(error); }
    finally {busy=false;$('progress-box').hidden=true;render();}
    return data.result;
  }
