    if(target.hasAttribute('data-save-project')||target.id==='save-project-side'){saveProject();return;}
    if(target.dataset.preset){const preset=S.presets.find(p=>p.id===target.dataset.preset);if(preset){active().cfg.areaScenario[preset.actionId]={enabled:true,coverage:1,intensity:1,preset:preset.id};markDirty();render();}return;}
    const handlers={run,export:()=>{if(!active().dirty&&active().result)$('export-dialog').showModal();},cancel:()=>{cancelled=true;registerController?.abort();$('progress-label').textContent='Avbryter…';},'close-export':()=>{$('export-dialog').close();},'download-csv':saveCSV,'download-audit':saveAudit,'download-offline':saveOffline,print:()=>window.print(),'import-project':()=>$('import-input').click(),'import-distance-data':()=>$('import-input').click(),'data-audit':saveAudit,'fetch-scb-register':fetchRegister,'apply-city-totals':()=>{try{applyCityTotals();}catch(error){setMessage(error.message,true);}},'reset-actions':()=>{active().cfg.areaScenario=S.initialState();markDirty();render();},'reset-distance-model':()=>{active().cfg.household.distanceModel=D.config({});markDirty();render();}};
    if(handlers[target.id])handlers[target.id]();
  });
  document.addEventListener('change',event=>{
    const node=event.target;if(busy)return;
    if(node.dataset.path==='mode'&&!isB()){active().cfg.mode=node.value==='network'?'network':'calibrated';markDirty();render();return;}
    if(node.dataset.path==='household.kmMode'&&isB()){if(!['local','national','deso_estimate'].includes(node.value))return;active().cfg.household.kmMode=node.value;if(node.value==='deso_estimate')active().cfg.household.distanceModel=D.config(active().cfg.household.distanceModel||{});markDirty();render();return;}
    if(node.dataset.edit){editInput(node);return;}
    if(node.dataset.action){try{editAction(node);render();}catch(error){setMessage(error.message,true);}return;}
    if(node.id==='exploitation-enabled'){active().cfg.exploitation={newHouseholds:0,carsPerHousehold:1,kmPerCar:active().cfg.household.kmMode==='deso_estimate'?null:active().cfg.household.kmPerCar,...active().cfg.exploitation,city,enabled:node.checked};markDirty();return;}
    if(node.id==='exploitation-deso'){active().cfg.exploitation={newHouseholds:0,carsPerHousehold:1,kmPerCar:active().cfg.household.kmMode==='deso_estimate'?null:active().cfg.household.kmPerCar,...active().cfg.exploitation,city,deso:node.value};markDirty();return;}
    if(node.id==='map-period'){period=node.value;render();return;}
    if(node.id==='map-metric'){metric=node.value;render();return;}
    if(node.id==='calc-area'){selected=node.value;render();return;}
    if(node.id==='scenario-note'){active().cfg.scenarioNote=node.value;markDirty();return;}
    if(node.id==='import-input')importFile(node.files?.[0]);
  });
  document.addEventListener('input',event=>{if(event.target.id==='area-search'){search=event.target.value;$('area-table').innerHTML=areaTable();}});
  document.addEventListener('keydown',event=>{const row=event.target.closest('[data-area]');if(row&&event.key==='Enter'&&row.tagName==='TR')selectArea(row.dataset.area,true);});
  window.VagvisApp={run,fetchRegister,setModel:next=>{if(state[next]&&!busy){model=next;selected='city|'+city;render();}},setView:next=>{if(titles[next]){view=next;render();}},getModel:()=>model,getCity:()=>city,getProject:()=>active().project,getConfig:()=>active().cfg,getResult:()=>active().result,getAudit:auditFile,render};
  const packaged = read('embedded-result',null);
  // Reuse only a freshly built result with an exact version and input fingerprint.
  const a=state.territorial;
  if(packaged?.version===V.VERSION && packaged.fingerprint===V.fingerprint(a.project,a.cfg)) { a.result=packaged;a.dirty=false; }
  render();
  window.VagvisApp.ready=active().result?Promise.resolve(active().result):run();
})();
